mapper.select:
SELECT

FROM ai_conversation_message
WHERE id = #{id,jdbcType=BIGINT}
  AND conversation_id = #{conversationId,jdbcType=BINARY}

SELECT

FROM ai_conversation_message
WHERE conversation_id = #{conversationId,jdbcType=BINARY}
  AND id > #{afterMessageId,jdbcType=BIGINT}
ORDER BY id ASC
LIMIT #{limit,jdbcType=INTEGER}

SELECT

FROM ai_conversation_message
WHERE conversation_id = #{conversationId,jdbcType=BINARY}
  AND id > #{afterMessageId,jdbcType=BIGINT}
  AND id <= #{cutoffMessageId,jdbcType=BIGINT}
ORDER BY id ASC
LIMIT #{limit,jdbcType=INTEGER}

SELECT MAX(id)
FROM ai_conversation_message
WHERE conversation_id = #{conversationId,jdbcType=BINARY}

SELECT message.id AS message_id, message.conversation_id, message.content_text, message.content_attachments::TEXT AS content_attachments_json, message.question_tokens, message.response_attachments::TEXT AS response_attachments_json, message.created_at, usage.id AS usage_id, usage.ai_model_id, model.model_name, usage.prompt_tokens, usage.cached_prompt_tokens, usage.completion_tokens, usage.reasoning_tokens, usage.charged_quota_minor, usage.finish_reason FROM ai_conversation_message message INNER JOIN ai_conversation conversation ON conversation.id = message.conversation_id INNER JOIN ai_model_usage_detail detail ON detail.conversation_message_id = message.id AND detail.conversation_id = message.conversation_id INNER JOIN ai_model_usage usage ON usage.id = detail.usage_id AND usage.login_identity_id = conversation.login_identity_id INNER JOIN ai_model model ON model.id = usage.ai_model_id WHERE message.conversation_id = #{conversationId,jdbcType=BINARY} AND conversation.login_identity_id = #{loginIdentityId,jdbcType=BIGINT} AND conversation.is_active = TRUE
AND message.id < #{beforeMessageId,jdbcType=BIGINT}
ORDER BY message.id DESC LIMIT #{limit,jdbcType=INTEGER}
